/* FRAME Studio element effects v1 */
import {createChromeBackground, installTiltLighting} from './chrome-background.js';
const previous=window.__frameElementEffectsExport;previous?.destroy();
let disposed=false,controller,observer,fallback,stopTilt,queued=false,bindings={},nodes=new Map(),originals=new WeakMap(),suppressed=new Set(Array.isArray(window.__frameElementEffectsPreviewIds)?window.__frameElementEffectsPreviewIds:[]);
const load=async file=>{if(!/^(?:manifest\.json|assets\/s[a-f0-9]{24}_[A-Za-z][A-Za-z0-9_-]{0,63}_[A-Za-z][A-Za-z0-9_-]{0,63}\.(?:vert|frag|wgsl|texture\.txt))$/.test(file))throw Error('Invalid FRAME element effects dependency');const response=await fetch(new URL(file,import.meta.url),{redirect:'error',credentials:'same-origin'});if(!response.ok)throw Error('FRAME element effects dependency unavailable: '+file);return response.text();};
const targets=id=>{if(!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(id))throw Error('Invalid FRAME element effects target');return Array.from(document.querySelectorAll('[data-localframe-id="'+id+'"]'));};
function capture(){const fresh=Object.keys(bindings).flatMap(id=>targets(id)).filter(node=>!originals.has(node));if(!fresh.length)return;const read=()=>{for(const node of fresh){const style=window.getComputedStyle(node),values={};for(let i=0;i<style.length;i++){const name=style[i],value=style.getPropertyValue(name);values[name]=value;values[name.replace(/-([a-z])/g,(_,letter)=>letter.toUpperCase())]=value;}for(const name of ['display','isolation','overflow','transform','filter','transitionDuration','animationName','animationDuration','position','left','top','width','height','boxSizing','flexDirection','flexWrap','justifyContent','alignItems','gridTemplateColumns','gap','padding','paddingTop','paddingRight','paddingBottom','paddingLeft','order','backgroundColor','color','fontSize','borderRadius','opacity'])values[name]=style.getPropertyValue(name.replace(/[A-Z]/g,letter=>'-'+letter.toLowerCase()));originals.set(node,values);}};if(typeof window.__frameElementEffectsPreviewBaseline==='function')window.__frameElementEffectsPreviewBaseline(read);else read();}
function baseline(id){if(!Object.hasOwn(bindings,id))return;const list=targets(id);if(list.length!==1)return;const values=originals.get(list[0]);return values?{...values}:undefined;}
function snapshot(){return new Map(Object.keys(bindings).filter(id=>!suppressed.has(id)).map(id=>[id,Array.from(document.querySelectorAll('[data-localframe-id="'+id+'"]'))]));}
function sync(force=false){if(disposed||!controller)return;capture();const next=snapshot();if(!force&&next.size===nodes.size&&Array.from(next).every(([id,list])=>{const old=nodes.get(id);return old&&old.length===list.length&&list.every((node,i)=>node===old[i]);}))return;nodes=next;controller.setBindings(Object.fromEntries(Object.entries(bindings).filter(([id])=>!suppressed.has(id))));}
function schedule(){if(queued||disposed)return;queued=true;queueMicrotask(()=>{queued=false;sync();});}
function setSuppressed(ids){suppressed=new Set(Array.isArray(ids)?ids.filter(id=>typeof id==='string'):[]);sync();}
const preview=event=>setSuppressed(event.detail?.ids??event.detail??[]);
function destroy(){if(disposed)return;disposed=true;observer?.disconnect();controller?.destroy();fallback?.destroy();stopTilt?.();window.removeEventListener('frame-element-effects-preview',preview);window.removeEventListener('pagehide',destroy);if(window.__frameElementEffectsExport===api)delete window.__frameElementEffectsExport;}
const api={setSuppressed,baseline,destroy};window.__frameElementEffectsExport=api;
window.addEventListener('frame-element-effects-preview',preview);window.addEventListener('pagehide',destroy);
if(import.meta.hot)import.meta.hot.dispose(destroy);
function useFallback(){if(disposed||fallback)return;controller?.destroy();controller=undefined;fallback=createChromeBackground(document.getElementById('coachConsole'));}
void(async()=>{stopTilt=installTiltLighting(document.getElementById('coachConsole'));if(matchMedia('(max-width: 600px)').matches||!navigator.gpu){useFallback();return;}const manifest=JSON.parse(await load('manifest.json'));bindings=manifest.bindings;for(const stack of Object.values(bindings))for(const entry of stack.entries)if(entry.kind==='shader'){for(const pass of entry.document.passes){pass.vertex=await load(pass.vertex.slice(6));pass.fragment=await load(pass.fragment.slice(6));}for(const texture of entry.document.textures??[])texture.dataUrl=await load(texture.dataUrl.slice(6));for(const definition of entry.document.componentEngine?.customComponents??[])definition.source=await load(definition.source.slice(6));}if(disposed)return;const {createElementEffectsController}=await import('./runtime.js');if(disposed)return;controller=createElementEffectsController(document,status=>{if(!status.compatible){console.warn('FRAME element effect:',status.id,status.message);useFallback();}});controller.setInteractive(false);observer=new MutationObserver(schedule);observer.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['data-localframe-id']});sync(true);})().catch(error=>{if(!disposed){console.warn('Using compatible chrome lighting:',error);useFallback();}});
